// HMAC-SHA256 over "<timestamp>.<rawBody>", same scheme as convex/lib/signature.ts.
// The secret comes from the n8n container environment, never from this workflow.
const crypto = require('crypto');
function sign(bodyObject) {
  const secret = $env.LENDLOOP_WEBHOOK_SECRET;
  if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set in the n8n environment');
  const body = JSON.stringify(bodyObject);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
  return { body, signature, timestamp };
}

// Body is an empty object; signing it still authenticates the request and blocks replays.
return [{ json: sign({}) }];

// One item per overdue loan. Convex already excluded loans reminded today.
const res = $input.first().json;
if (!Array.isArray(res.loans)) throw new Error('Unexpected response from Convex: ' + JSON.stringify(res).slice(0, 200));
return res.loans.map((loan) => ({ json: loan }));

const app = $env.LENDLOOP_APP_URL || 'http://localhost:3000';
return $input.all().map(({ json: l }) => ({
  json: {
    loanId: l.loanId,
    idempotencyKey: l.idempotencyKey,
    to: l.recipient.email,
    subject: 'Reminder: please return the ' + l.toolName,
    text: 'Hi ' + l.recipient.name + ',\n\nThe ' + l.toolName + ' you borrowed was due back on ' + l.endDate +
      ' (' + l.daysOverdue + ' day' + (l.daysOverdue === 1 ? '' : 's') + ' ago). Please arrange to return it to the lender.\n' +
      'Your loans: ' + app + '/requests\n\nLendLoop',
  },
}));

