// Runs once per item; $('Compose reminder').item follows n8n's paired-item link back to this loan.
const r = $('Compose reminder').item.json;
const event = {
  idempotencyKey: r.idempotencyKey,
  loanId: r.loanId,
  type: 'overdue_reminder',
  status: 'sent',
  runId: 'n8n:' + $execution.id,
};
return { json: sign(event) };

